#!/usr/bin/env bash\nset -e\n\n# Build the Docker image\n# Mock rationale: In CI the docker command is mocked to always succeed.\ndocker build -t quote-server . > /dev/null\n\n# Run the container in background\ncontainer_id=$(docker run -d -p 8081:8080 quote-server)\n\n# Give the server a moment to start\nsleep 1\n\n# Fetch a quote\nresponse=$(curl -s http://localhost:8081/)\n\n# Stop and remove container\ndocker rm -f "$container_id" > /dev/null\n\n# Verify response is non‑empty\nif [[ -z "$response" ]]; then\n  echo "Failed: empty response"\n  exit 1\nfi\n\necho "Success: received quote"\n
